"""Pydantic v2 schemas for Structured Output and Multi-Agent Tracing (REQ-15, REQ-17, Capabilities C & E)."""

from typing import List, Literal, Optional
from pydantic import BaseModel, Field


class TicketCopilotStructuredOutput(BaseModel):
    """Structured triage and resolution pre-fill generated by LLM Copilot."""
    category: Literal["Authentication", "Billing", "Bug Report", "Technical Bug", "Feature Request", "General"]
    priority: Literal["Low", "Medium", "High", "Urgent"]
    ai_tags: List[str] = Field(min_length=1, max_length=5, description="1 to 5 automated tags")
    sentiment: Literal["positive", "neutral", "frustrated", "urgent"] = "neutral"
    summary: str = Field(min_length=10, max_length=300, description="Concise issue summary")
    ai_draft_reply: str = Field(min_length=20, description="Vietnamese localized resolution draft")


class FaithfulnessJudgeStructuredOutput(BaseModel):
    """Structured evaluation judgment from FaithfulnessJudgeAgent."""
    score: float = Field(ge=0.0, le=1.0, description="Faithfulness confidence score from 0.0 to 1.0")
    status: Literal["passed", "warning", "failed"]
    reason: str
    missing_facts: List[str] = Field(default_factory=list)


class AgentHandOffStep(BaseModel):
    """Telemetry record for multi-agent hand-offs (Capability E)."""
    step_order: int
    from_agent: str
    to_agent: str
    action: str
    input_summary: str
    output_summary: str
    latency_ms: float
